// Reports only navigate. Training selection previews the existing real action.
var preparationTrainingReceipt=null;
function showPreparationTrainingReceipt(){
 const r=preparationTrainingReceipt;if(!r||operationsSection!=='training-card'||r.seed!==season.seed||r.year!==season.year||r.round!==season.round||r.focus!==season.trained||r.rows.some(p=>season.squad[p.id]?.identity!==p.identity||season.squad[p.id][p.key]!==p.after||season.squad[p.id].energy!==p.energyAfter))return;
 const box=$('training-card').querySelector('.operations-team-current');if(!box)return;
 box.classList.add('preparation-training-receipt');box.innerHTML='<h3>이번 훈련 직후 결과 · '+r.label+' · '+r.rows.length+'명</h3><ul>'+r.rows.map(p=>'<li><strong>'+escapeText(p.name)+'</strong><span>'+p.keyLabel+' '+trainingDisplayNumber(p.before)+' → '+trainingDisplayNumber(p.after)+'</span><b>체력 '+trainingDisplayNumber(p.energyBefore)+' → '+trainingDisplayNumber(p.energyAfter)+'</b></li>').join('')+'</ul>';
}
function prepareTrainingChoices(){
 if(operationsSection!=='training-card')return;const select=$('training-focus'),actions=$('training-card').querySelector('.training-actions');if(!select||!actions)return;
 let choices=actions.querySelector('.preparation-training-choices');if(!choices){choices=document.createElement('div');choices.className='preparation-training-choices';choices.setAttribute('role','group');choices.setAttribute('aria-label','팀 훈련 종류와 효과 비교');actions.prepend(choices);}
 const rows=PreparationDesk.training(season);choices.innerHTML=rows.map(p=>'<button type="button" data-team-focus="'+p.focus+'" aria-pressed="'+(p.focus===select.value)+'" '+(!p.available?'disabled':'')+'><b>'+p.label+'</b><span>'+(p.available?(p.focus==='recovery'?'체력 회복 '+p.changed+'명':'능력 향상 '+p.changed+'명'):'현재 실행 불가')+'</span><small>'+(p.available?'평균 체력 '+Math.round(p.energyBefore)+' → '+Math.round(p.energyAfter):season.trained?'이번 주 훈련 완료':S.ready(season)?'시즌 종료':'리그 준비 때 열림')+'</small></button>').join('');
 choices.onclick=e=>{const b=e.target.closest('[data-team-focus]');if(!b||b.disabled)return;select.value=b.dataset.teamFocus;select.dispatchEvent(new Event('change',{bubbles:true}));choices.querySelector('[data-team-focus="'+select.value+'"]')?.focus({preventScroll:true});};
 const execute=$('train');if(execute&&!execute.preparationCaptured){execute.preparationCaptured=true;execute.addEventListener('click',()=>{execute.preparationPending={campaign:season,focus:select.value,preview:S.trainingPreview(season,select.value),label:rows.find(p=>p.focus===select.value).label};},{capture:true});}
 showPreparationTrainingReceipt();
}
function renderPreparationDesk(){
 if(operationsSection!=='club-overview')return;const d=PreparationDesk.read(season);if(!d.valid)return;const host=$('club-overview'),esc=escapeText;
 const f=d.fixture,fixture=f?'<div class="preparation-opponent"><header>'+clubMark(f.club)+'<div><h3>'+esc(f.club.name)+'</h3><span>'+(f.home?'홈':'원정')+' · '+f.formation.split('').join('-')+' · '+(d.phase==='prep'?'경기 전 예상':'현재 경기 상대')+'</span></div></header><p>요주의 '+esc(f.keyPlayer.name)+' · '+esc(f.keyPlayer.threat)+'</p><div class="preparation-comparisons">'+f.comparisons.map(r=>'<div><span>'+esc(r.label)+'</span><b>'+Math.round(r.ours)+'</b><i>대</i><b>'+Math.round(r.opponent)+'</b></div>').join('')+'</div><small>우리 대 상대 · 현재 경기 전력 분석</small></div>':'<div class="preparation-opponent"><h3>이번 시즌 완료</h3><p>확정 순위와 기록을 확인하세요. 다음 시즌은 홈의 시즌 결산에서 직접 시작합니다.</p></div>';
 const form=d.last.length?d.last.map(r=>'<li class="preparation-form-'+r.outcome+'"><b>'+r.goals.join(' : ')+'</b><span>'+esc(r.opponent)+'</span></li>').join(''):'<li><span>확정 리그 경기 대기</span></li>';
 host.innerHTML='<section class="preparation-desk"><header class="preparation-desk-title"><h2>구단 현황 · 경기 준비 보고</h2><span>'+d.year+'시즌 · '+d.division+'부 · '+(d.finished?'시즌 종료':d.phase==='prep'?'경기 전':d.phase==='full'?'정산 대기':'경기 중')+'</span></header><dl class="preparation-metrics">'+[['리그 순위',d.rank?d.rank+'위':'미정'],['승점',d.points+'점'],['시즌 진행',d.round+'/'+d.rounds],['주요 능력 평균',d.average.toFixed(1)],['출전 가능',d.available+'/'+d.total],['구단 자금',(d.balance<0?'−':'')+moneyLabel(d.balance)]].map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl><div class="preparation-main"><section class="preparation-fixture">'+fixture+'<div class="preparation-stadium">'+ClubGrowth.html(d.division)+'</div><div class="preparation-last"><h3>최근 확정 리그 경기</h3><ul>'+form+'</ul></div></section><section class="preparation-reports" aria-label="수석코치 준비 보고">'+d.reports.map(r=>'<article data-preparation-tone="'+r.tone+'"><header><h3>'+r.title+'</h3><b>'+esc(r.value)+'</b></header><p>'+esc(r.note)+'</p></article>').join('')+'</section></div><footer class="preparation-actions"><button type="button" data-preparation-target="squad-health">몸 상태</button><button type="button" data-preparation-target="training-card">훈련 비교</button><button type="button" data-preparation-view="tactics" '+(d.lineup?.recommendations.length?'data-preparation-coach':'')+'>'+(d.lineup?.recommendations.length?'선발 비교 '+d.lineup.recommendations.length+'명':'전술 준비')+'</button><button type="button" data-preparation-view="'+(d.finished?'cup':'match')+'" class="primary">'+(d.finished?'대회 성적':d.phase==='full'?'경기 결과':'경기 준비')+'</button></footer></section>';
 ClubArt.fitDrama?.(host);
}
const preparationOriginal=prepareOperationsPage;prepareOperationsPage=function(){preparationOriginal();prepareTrainingChoices();renderPreparationDesk();};
const preparationTeamOriginal=renderTeamTrainingPreview;renderTeamTrainingPreview=function(){preparationTeamOriginal();prepareTrainingChoices();};
managementDialog.addEventListener('click',e=>{const train=e.target.closest('#train'),pending=train?.preparationPending;if(pending){delete train.preparationPending;const {campaign,focus,preview,label}=pending;if(preview.available&&campaign===season&&season.trained===focus){const labels={keeping:'선방',defense:'수비',passing:'패스',attack:'결정력',speed:'속도',endurance:'지구력',energy:'체력'};preparationTrainingReceipt={seed:season.seed,year:season.year,round:season.round,focus,label,rows:preview.rows.map(p=>({...p,keyLabel:labels[p.key],after:season.squad[p.id][p.key],energyAfter:season.squad[p.id].energy}))};showPreparationTrainingReceipt();}}const b=e.target.closest('[data-preparation-target],[data-preparation-view]');if(!b)return;if(b.hasAttribute('data-preparation-coach')){closeOperationsPage();coachLineupPriority='strength';coachLineupNotice='';coachLineupShape=state.formation;coachLineupReview=null;openTacticsEditor('lineup',b);}else if(b.dataset.preparationTarget)openManagementPanel(b.dataset.preparationTarget,b);else{closeOperationsPage();setView(b.dataset.preparationView);}});
